// End-to-end verification against the actual BrightNest_Test_Import_Workbook.xlsx
// fixture (generated by test-fixtures/generate-test-workbook.cjs to match the
// exact spec: a README sheet first, followed by Sales_Test, Expenses_Test,
// Vendors_Test, Purchases_Test, Salaries_Test, Inventory_Test,
// Import_Test_Cases, and Profit_Share_Test). These tests reproduce the
// original bug (README misread as transaction data) and confirm the fix.

import { describe, it, expect, beforeAll } from 'vitest'
import { readFileSync } from 'node:fs'
import path from 'node:path'
import {
  listWorksheets,
  readSheet,
  suggestWorksheetForCategory,
  detectHeaderRow,
  looksInformationalSheet,
} from '@/lib/import/parseFile'

const FIXTURE_PATH = path.resolve(__dirname, '../../test-fixtures/BrightNest_Test_Import_Workbook.xlsx')

/** jsdom's File/Blob polyfill does not implement arrayBuffer()/text(), which
 *  parseFile.ts relies on (as it does in real browsers). Build a File-like
 *  object backed directly by the real fixture bytes read fresh from disk on
 *  every call, so there is no risk of a stale/corrupted buffer reference. */
function loadFixtureAsFile(): File {
  const bytes = readFileSync(FIXTURE_PATH)
  const arrayBuffer = bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength) as ArrayBuffer
  const file = new File([bytes], 'BrightNest_Test_Import_Workbook.xlsx', {
    type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  })
  // Override the instance methods directly (not the shared prototype) so
  // each fixture File carries its own correct bytes regardless of jsdom's
  // Blob internals.
  Object.defineProperty(file, 'arrayBuffer', {
    value: async () => arrayBuffer.slice(0),
  })
  Object.defineProperty(file, 'text', {
    value: async () => bytes.toString('utf-8'),
  })
  return file
}

let file: File

beforeAll(() => {
  file = loadFixtureAsFile()
})

describe('worksheet listing (fixes: no longer silently imports the first sheet)', () => {
  it('lists every worksheet actually present in the workbook, inventing none', async () => {
    const sheets = await listWorksheets(file)
    const names = sheets.map((s) => s.name)
    expect(names).toEqual([
      'README',
      'Sales_Test',
      'Expenses_Test',
      'Vendors_Test',
      'Purchases_Test',
      'Salaries_Test',
      'Inventory_Test',
      'Import_Test_Cases',
      'Profit_Share_Test',
    ])
  })

  it('flags the README sheet as informational, not transaction data', async () => {
    const sheets = await listWorksheets(file)
    const readme = sheets.find((s) => s.name === 'README')!
    expect(readme.looksInformational).toBe(true)
  })

  it('does not flag Sales_Test or Expenses_Test as informational', async () => {
    const sheets = await listWorksheets(file)
    expect(sheets.find((s) => s.name === 'Sales_Test')!.looksInformational).toBe(false)
    expect(sheets.find((s) => s.name === 'Expenses_Test')!.looksInformational).toBe(false)
  })

  it('reports an approximate row count per sheet so the UI can show it in the picker', async () => {
    const sheets = await listWorksheets(file)
    const sales = sheets.find((s) => s.name === 'Sales_Test')!
    // 1 header row + 24 data rows = 25 non-empty rows.
    expect(sales.approxRowCount).toBe(25)
  })

  it('suggests Sales_Test for the "sales" category and Expenses_Test for the "expenses" category', async () => {
    const sheets = await listWorksheets(file)
    expect(suggestWorksheetForCategory(sheets, 'sales')).toBe('Sales_Test')
    expect(suggestWorksheetForCategory(sheets, 'expenses')).toBe('Expenses_Test')
  })

  it('never suggests a worksheet name that is not actually present in the workbook', async () => {
    const sheets = await listWorksheets(file)
    const suggestion = suggestWorksheetForCategory(sheets, 'purchases')
    if (suggestion) {
      expect(sheets.map((s) => s.name)).toContain(suggestion)
    }
  })
})

describe('header detection on the real workbook (fixes: README text treated as headers)', () => {
  it('does NOT confidently detect a header row on the README sheet (it is prose, not column labels)', async () => {
    const result = await readSheet(file, 'README')
    expect(result.headerDetectionUncertain).toBe(true)
  })

  it('does not mistake the README title row for column headers like "Description"/"Reference number"', async () => {
    const result = await readSheet(file, 'README')
    // The old bug mapped README prose into headers; confirm the detected
    // header row is just the single title cell, not a multi-column header.
    expect(result.headers.length).toBeLessThanOrEqual(1)
  })

  it('confidently detects the real header row on Sales_Test as row 1 (index 0)', async () => {
    const result = await readSheet(file, 'Sales_Test')
    expect(result.headerDetectionUncertain).toBe(false)
    expect(result.headerRowIndex).toBe(0)
  })

  it('confidently detects the real header row on Expenses_Test as row 1 (index 0)', async () => {
    const result = await readSheet(file, 'Expenses_Test')
    expect(result.headerDetectionUncertain).toBe(false)
    expect(result.headerRowIndex).toBe(0)
  })
})

describe('Sales_Test worksheet content (fixes: core reported bug)', () => {
  it('detects all nine expected Sales_Test columns', async () => {
    const result = await readSheet(file, 'Sales_Test')
    expect(result.headers).toEqual(['Date', 'Canteen', 'Reference', 'Description', 'Amount', 'Cash', 'UPI', 'Card', 'Notes'])
  })

  it('detects exactly 24 Sales_Test data rows, not README paragraphs', async () => {
    const result = await readSheet(file, 'Sales_Test')
    expect(result.rows).toHaveLength(24)
  })

  it('shows real sales records such as SALE-1001 in the data, not README text', async () => {
    const result = await readSheet(file, 'Sales_Test')
    const references = result.rows.map((r) => String(r[2]))
    expect(references).toContain('SALE-1001')
    expect(references.join(' ')).not.toMatch(/BrightNest Local Dashboard/)
    expect(references.join(' ')).not.toMatch(/Suggested test/)
  })

  it('every data row is a real transaction row, never the README title or instructions', async () => {
    const result = await readSheet(file, 'Sales_Test')
    const flatText = result.rows.map((r) => r.join(' ')).join(' ')
    expect(flatText).not.toMatch(/Test Import Workbook/)
    expect(flatText).not.toMatch(/All records are fictional/)
  })
})

describe('Expenses_Test worksheet content', () => {
  it('detects all eight expected Expenses_Test columns', async () => {
    const result = await readSheet(file, 'Expenses_Test')
    expect(result.headers).toEqual(['Date', 'Canteen', 'Reference', 'Category', 'Vendor', 'Amount', 'Payment Method', 'Description'])
  })

  it('detects exactly 24 Expenses_Test data rows', async () => {
    const result = await readSheet(file, 'Expenses_Test')
    expect(result.rows).toHaveLength(24)
  })
})

describe('Import_Test_Cases worksheet (deliberately invalid/duplicate rows)', () => {
  it('reads the dedicated test-case sheet separately from Sales_Test/Expenses_Test', async () => {
    const result = await readSheet(file, 'Import_Test_Cases')
    expect(result.headers).toEqual(['Date', 'Canteen', 'Reference', 'Description', 'Amount'])
    expect(result.rows.length).toBeGreaterThan(0)
  })
})

describe('generic header-row detection and informational-sheet heuristics (unit level)', () => {
  it('detectHeaderRow finds a row of short plausible labels over a long title row', () => {
    const matrix = [
      ['A long descriptive title that is definitely not a header row at all'],
      [''],
      ['Date', 'Canteen', 'Amount', 'Reference'],
      ['2026-10-01', 'Lower Parel', '500', 'REF-1'],
    ]
    const { index, confident } = detectHeaderRow(matrix)
    expect(index).toBe(2)
    expect(confident).toBe(true)
  })

  it('detectHeaderRow is not confident when no row looks like a header', () => {
    const matrix = [['Just some notes.'], ['More free-form prose here.'], ['Even more unrelated text.']]
    const { confident } = detectHeaderRow(matrix)
    expect(confident).toBe(false)
  })

  it('looksInformationalSheet flags a sheet named "Instructions" regardless of content', () => {
    expect(looksInformationalSheet('Instructions', [['Date', 'Amount']])).toBe(true)
  })

  it('looksInformationalSheet does not flag a normally named sheet with a confident header', () => {
    const matrix = [['Date', 'Canteen', 'Amount'], ['2026-10-01', 'Lower Parel', '500']]
    expect(looksInformationalSheet('Sales_Test', matrix)).toBe(false)
  })
})
